/**
 * Venue registry — resolves a tenant (venue) by slug.
 *
 * `src/data/provisioned_venues.json` is a read-only registry generated by
 * `scripts/generate-jaleo-venue.ts`. The app resolves a venue from the URL
 * (`?v=<slug>` / `?venue=<slug>`) and falls back to the first active venue
 * when no slug is given.
 */
import registry from '@/data/provisioned_venues.json';
import type { MenuCategoryDetail, Venue } from '@/types/mimenu';

interface RegistryItem {
  id: string;
  slug: string;
  name: string;
  tagline: string;
  description: string;
  city: string;
  address?: string;
  phone?: string;
  whatsapp?: string;
  currency: string;
  primary_color?: string;
  background_theme?: string;
  is_active: boolean;
  categories?: MenuCategoryDetail[];
  tables?: number | Array<Record<string, unknown>>;
}

const ITEMS = (registry as unknown as RegistryItem[]).filter((v) => v?.slug);

/** Slugs that must not be resolved from the registry (app routes). */
const RESERVED_SLUGS = new Set([
  'auth', 'admin', 'menu', 'checkout', 'checkout2', 'payment', 'order',
  'order-status', 'order-lookup', 'waiter', 'kitchen', 'cashier', 'reports',
  'monitoring', 'onboarding', 'proposta', 'landing-menu', 'contract-management',
  'diagnostic', 'whatsapp-admin', 'customers', 'waiter-dashboard',
  'old', 'old3', 'old4', 'old5', 'old6', 'old7', 'takeat', 'saas',
  'cardapio-digital', 'landing-genio', 'print-server-config',
  'waiter-management', 'waiter-diagnostic', 'waiter/setup', 'waiter/setup',
  'admin/ai', 'admin/ingester', 'admin/ingest-menu', 'admin/offers',
  'admin/analytics', 'admin/tables', 'admin/reviews', 'admin/branding',
  'admin/products', 'admin/settings', 'admin/waiter-reports',
]);

export function isReservedSlug(slug: string): boolean {
  return RESERVED_SLUGS.has(slug.toLowerCase());
}

/** Every resolvable tenant slug, for pickers and validation. */
export function listVenueSlugs(): string[] {
  return ITEMS.map((v) => v.slug);
}

/** Find a venue by slug. Returns null for unknown or reserved slugs. */
export function findVenueBySlug(slug: string): RegistryItem | null {
  if (!slug || isReservedSlug(slug)) return null;
  return ITEMS.find((v) => v.slug === slug) || null;
}

/**
 * Resolve the active venue slug from the current URL.
 * Returns the requested slug plus whether it was actually found.
 */
export function resolveVenueSlug(search: string): { slug: string; requested: string | null; found: boolean } {
  const params = new URLSearchParams(search);
  const requested = params.get('v') || params.get('venue');
  if (requested) {
    const found = !!findVenueBySlug(requested);
    return { slug: found ? requested : defaultVenueSlug(), requested, found };
  }
  return { slug: defaultVenueSlug(), requested: null, found: true };
}

/**
 * The tenant shown when the URL carries no `?v=` slug.
 * This is the demo venue, NOT the first customer (Jaleo).
 */
export const DEFAULT_VENUE_SLUG = 'demo';

export function defaultVenueSlug(): string {
  return ITEMS.some((v) => v.slug === DEFAULT_VENUE_SLUG) ? DEFAULT_VENUE_SLUG : (ITEMS[0]?.slug || 'demo');
}

/** Find the default venue entry, or null when the registry has none. */
export function findDefaultVenue(): RegistryItem | null {
  return findVenueBySlug(defaultVenueSlug());
}

/** Coerce a registry entry into the `Venue` shape the app consumes. */
export function toVenue(item: RegistryItem): Venue {
  return {
    id: item.id,
    slug: item.slug,
    name: item.name,
    tagline: item.tagline || item.name,
    description: item.description || '',
    city: item.city || '',
    address: item.address || '',
    phone: item.phone || '',
    whatsapp: item.whatsapp || '',
    currency: item.currency || 'Bs.',
    currency_code: 'BOB',
    logo_url: '',
    banner_url: '',
    primary_color: item.primary_color || '#BC6C25',
    accent_color: '#F2EEE4',
    background_theme: item.background_theme === 'dark' ? 'dark' : 'light',
    opening_hours: '',
    is_active: item.is_active !== false,
  };
}

/** Menu categories for a venue, or an empty list when the venue has none. */
export function categoriesFor(item: RegistryItem): MenuCategoryDetail[] {
  return (item.categories || []) as MenuCategoryDetail[];
}

/** Table count for a venue; registry stores either a count or a table array. */
export function tableCountFor(item: RegistryItem): number {
  if (typeof item.tables === 'number') return item.tables;
  if (Array.isArray(item.tables)) return item.tables.length;
  return 8;
}
